 const [records,setRecords]=useState<Record<string,Row[]>>({}),[tab,setTab]=useState(''),[loading,setLoading]=useState(true),[errors,setErrors]=useState<Record<string,string>>({}),[oneTimeSecret,setOneTimeSecret]=useState(''),[dryRunResult,setDryRunResult]=useState<any>(null),[selectedWorkflow,setSelectedWorkflow]=useState(''),[dealFilters,setDealFilters]=useState<{startDate?:string;endDate?:string}>({});
