function ValueView({value}:{value:any}):React.ReactNode{
 if(value==null)return <span>Not set</span>;
 if(Array.isArray(value)){if(!value.length)return <span>None</span>;if(value.every(v=>typeof v!=='object'))return <span>{value.join(', ')}</span>;return <div>{value.map((v,i)=><ValueView key={i} value={v}/>)}</div>}
 if(typeof value==='object')return <dl className="record-details">{Object.entries(value).filter(([key])=>!['id','tokenHash','token_hash'].includes(key)).map(([key,v])=><React.Fragment key={key}><dt>{label(key.replace(/([a-z])([A-Z])/g,'$1 $2'))}</dt><dd><ValueView value={v}/></dd></React.Fragment>)}</dl>;
 return <span>{typeof value==='boolean'?value?'Yes':'No':String(value)}</span>;
}
